\centering
\caption{Summary of drag coefficients calculated with the existing processing assumptions. Across-speed standard deviation is descriptive only.}
\label{tab:summary}
\begin{tabular}{lrrrr}
\toprule
Cylinder & Runs & Mean $C_D$ & Across-speed SD & Range \\
\midrule
1 in (\SI{25.4}{mm}) & 10 & 1.144 & 0.033 & 1.094--1.182 \\
1.5 in (\SI{38.1}{mm}) & 10 & 1.153 & 0.026 & 1.104--1.193 \\
2 in (\SI{50.8}{mm}) & 10 & 1.178 & 0.070 & 1.108--1.357 \\
\bottomrule
